def clean(df):
    df['species'] = df['species'].str.title()
    df = df[df['species'].isin(['Adelie', 'Chinstrap', 'Gentoo'])]
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235)]
    df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    return df

def answer(df):
    avg_body_mass = df.groupby('species')['body_mass_g'].mean().to_dict()
    return avg_body_mass}
